17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    /**
109	     * Rejects an owner payload that is missing or blank in any of the required fields
110	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
111	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
112	     * value as present; this guard closes that gap so a blank in any required field is
113	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
114	     * the name of each offending field.
115	     */
116	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto) {
117	        List<String> missing = new ArrayList<>();
118	        if (isBlank(ownerFieldsDto.getFirstName())) {
119	            missing.add("firstName");
120	        }
121	        if (isBlank(ownerFieldsDto.getLastName())) {
122	            missing.add("lastName");
123	        }
124	        if (isBlank(ownerFieldsDto.getAddress())) {
125	            missing.add("address");
126	        }
127	        if (isBlank(ownerFieldsDto.getCity())) {
128	            missing.add("city");
129	        }
130	        if (isBlank(ownerFieldsDto.getTelephone())) {
131	            missing.add("telephone");
132	        }
133	        if (!missing.isEmpty()) {
134	            throw new MissingOwnerFieldsException(missing);
135	        }
136	    }
137	
138	    private static boolean isBlank(String value) {
139	        return value == null || value.isBlank();
140	    }
141	
142	    /**
143	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
144	     */
145	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
146	
147	    /**
148	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
149	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
150	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
151	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
152	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
153	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
154	     */
155	    private static String normalizeTelephone(String telephone) {
156	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
157	        String e164;
158	        if (cleaned.startsWith("+")) {
159	            e164 = cleaned;
160	        } else {
161	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
162	            e164 = "+61" + national;
163	        }
164	        if (!E164_PATTERN.matcher(e164).matches()) {
165	            throw new InvalidTelephoneException(telephone);
166	        }
167	        return e164;
168	    }
169	
170	    /**
171	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
172	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
173	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
174	     */
175	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
176	
177	    /**
178	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
179	     * optional). When present it must be a syntactically valid address; a valid value is
180	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
181	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
182	     */
183	    private static String normalizeEmail(String email) {
184	        if (email == null) {
185	            return null;
186	        }
187	        if (!EMAIL_PATTERN.matcher(email).matches()) {
188	            throw new InvalidEmailException(email);
189	        }
190	        return email.toLowerCase(Locale.ROOT);
191	    }
192	
193	    /**
194	     * Rejects a create whose normalized telephone is already used by another owner. Each
195	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
196	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
197	     * the format each was originally entered in. An existing value that cannot form a valid E.164
198	     * number is skipped rather than colliding. A match is reported via
199	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
200	     */
201	    private void rejectDuplicateTelephone(String normalizedTelephone) {
202	        for (Owner existing : this.clinicService.findAllOwners()) {
203	            String existingE164;
204	            try {
205	                existingE164 = normalizeTelephone(existing.getTelephone());
206	            } catch (InvalidTelephoneException ex) {
207	                continue;
208	            }
209	            if (normalizedTelephone.equals(existingE164)) {
210	                throw new DuplicateTelephoneException(normalizedTelephone);
211	            }
212	        }
213	    }
214	
215	    /**
216	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
217	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
218	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
219	     * spacing do not defeat the duplicate-household check.
220	     */
221	    private static String collapse(String value) {
222	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
223	    }
224	
225	    /**
226	     * Rejects a create that would place a second owner in the same household as an existing one -
227	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
228	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
229	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
230	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
231	     * translates to a 409.
232	     */
233	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
234	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
235	            return;
236	        }
237	        String lastName = collapse(ownerFieldsDto.getLastName());
238	        String address = collapse(ownerFieldsDto.getAddress());
239	        for (Owner existing : this.clinicService.findAllOwners()) {
240	            if (lastName.equals(collapse(existing.getLastName()))
241	                && address.equals(collapse(existing.getAddress()))) {
242	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
243	            }
244	        }
245	    }
246	
247	    /**
248	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
249	     * where {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN}
250	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners
251	     * (e.g. {@code 'SMI-0007'}).
252	     */
253	    private String nextCustomerCode(String lastName) {
254	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
255	        int sequence = this.clinicService.findAllOwners().size() + 1;
256	        return String.format("%s-%04d", last3, sequence);
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
262	        rejectMissingOrBlankFields(ownerFieldsDto);
263	        rejectDuplicateHousehold(ownerFieldsDto);
264	        HttpHeaders headers = new HttpHeaders();
265	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
266	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
267	        rejectDuplicateTelephone(normalizedTelephone);
268	        owner.setTelephone(normalizedTelephone);
269	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
270	        if (owner.getRegistrationDate() == null) {
271	            owner.setRegistrationDate(LocalDate.now());
272	        }
273	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
274	        this.clinicService.saveOwner(owner);
275	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
276	        headers.setLocation(UriComponentsBuilder.newInstance()
277	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
278	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
284	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
285	        if (currentOwner == null) {
286	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	        }
288	        currentOwner.setAddress(ownerFieldsDto.getAddress());
289	        currentOwner.setCity(ownerFieldsDto.getCity());
290	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
291	        currentOwner.setLastName(ownerFieldsDto.getLastName());
292	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
293	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
294	        this.clinicService.saveOwner(currentOwner);
295	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
296	    }
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Transactional
300	    @Override
301	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
302	        Owner owner = this.clinicService.findOwnerById(ownerId);
303	        if (owner == null) {
304	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
305	        }
306	        this.clinicService.deleteOwner(owner);
307	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner == null) {
315	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	        }
317	        HttpHeaders headers = new HttpHeaders();
318	        Pet pet = petMapper.toPet(petFieldsDto);
319	        owner.setId(ownerId);
320	        pet.setOwner(owner);
321	        pet.getType().setName(null);
322	        this.clinicService.savePet(pet);
323	        PetDto petDto = petMapper.toPetDto(pet);
324	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
325	            .buildAndExpand(pet.getId()).toUri());
326	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
327	    }
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Override
331	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
332	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
333	        if (currentOwner != null) {
334	            Pet currentPet = this.clinicService.findPetById(petId);
335	            if (currentPet != null) {
336	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
337	                currentPet.setName(petFieldsDto.getName());
338	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
339	                this.clinicService.savePet(currentPet);
340	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
341	            }
342	        }
343	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
344	    }
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
349	        HttpHeaders headers = new HttpHeaders();
350	        Visit visit = visitMapper.toVisit(visitFieldsDto);
351	        Pet pet = new Pet();
352	        pet.setId(petId);
353	        visit.setPet(pet);
354	        this.clinicService.saveVisit(visit);
355	        VisitDto visitDto = visitMapper.toVisitDto(visit);
356	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
357	            .buildAndExpand(visit.getId()).toUri());
358	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
359	    }
360	
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Override
364	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
365	        Owner owner = this.clinicService.findOwnerById(ownerId);
366	        if (owner != null) {
367	            Pet pet = owner.getPet(petId);
368	            if (pet != null) {
369	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
370	            }
371	        }
372	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
373	    }
374	}
